#!/bin/sh
# Start mitmproxy with the logging addon. Once the CA exists, publish ONLY its
# public certificate to /ca-public (shared read-only with the agents).
set -eu
CONF=/data/mitm

# Database password generated by the `init` service (readable by this user only).
if [ -z "${OBS_DB_DSN:-}" ]; then
  OBS_DB_DSN="postgresql://proxy_writer:$(cat /run/aab-secrets/proxy.pw)@db:5432/obs"
  export OBS_DB_DSN
fi

(
  while [ ! -s "$CONF/mitmproxy-ca-cert.pem" ]; do sleep 0.5; done
  cp "$CONF/mitmproxy-ca-cert.pem" /ca-public/.tmp-ca.pem
  mv /ca-public/.tmp-ca.pem /ca-public/mitmproxy-ca-cert.pem
  echo "[proxy] CA certificate published"
) &

exec mitmdump \
  --listen-host 0.0.0.0 --listen-port 8080 \
  --set confdir="$CONF" \
  --set stream_large_bodies=50m \
  --set flow_detail=0 \
  --set termlog_verbosity=warn \
  -s /app/obs_addon.py
